#include "GuiState.h"
#include "Paths.h"
#include "protocol-v3.hpp"
#include <QFile>
#include <QSaveFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QStringDecoder>
#include <limits>
#include <cmath>
namespace{
bool validGeometry(const QJsonObject&g){if(g.isEmpty())return true;if(g.keys()!=QStringList({"height","mode","width","x","y"}))return false;for(const auto&k:QStringList{"x","y","width","height"}){const auto v=g.value(k);const auto n=v.toDouble();if(!v.isDouble()||std::floor(n)!=n||std::abs(n)>10000000)return false;}const auto mode=g.value("mode").toString();return g.value("width").toInt()>=520&&g.value("width").toInt()<=16384&&g.value("height").toInt()>=400&&g.value("height").toInt()<=16384&&(mode=="windowed"||mode=="maximized"||mode=="fullscreen");}
bool privateFile(const QString&path){if(!PrivatePaths::file(path))return false;struct stat s{};return lstat(path.toUtf8().constData(),&s)<0?errno==ENOENT:s.st_nlink==1;}
bool read(const QString&path,qint64 max,QByteArray&bytes,bool&exists){if(!privateFile(path))return false;QFile file(path);exists=file.exists();if(!exists){bytes.clear();return true;}if(!file.open(QIODevice::ReadOnly)||file.size()>max)return false;bytes=file.readAll();if(file.error()!=QFileDevice::NoError)return false;QStringDecoder decoder(QStringDecoder::Utf8);decoder.decode(bytes);return !decoder.hasError();}
bool write(const QString&path,const QByteArray&bytes,qint64 max){if(bytes.size()>max||!privateFile(path)||!PrivatePaths::directory(QFileInfo(path).absolutePath(),true))return false;QSaveFile file(path);file.setDirectWriteFallback(false);if(!file.open(QIODevice::WriteOnly)||!file.setPermissions(QFileDevice::ReadOwner|QFileDevice::WriteOwner))return false;return file.write(bytes)==bytes.size()&&file.flush()&&::fsync(file.handle())==0&&file.commit()&&PrivatePaths::persistDirectory(QFileInfo(path).absolutePath());}
bool literal(const QString&s,qint64 max){const auto b=s.toUtf8();return b.size()<=max&&QString::fromUtf8(b)==s;}
QString draftPath(const QString&path,const QString&id){return QFileInfo(path).absolutePath()+"/drafts/"+id+".json";}
}
bool GuiState::validId(const QString&id){if(id.isEmpty()||id.size()>128||id[0]<'1'||id[0]>'9')return false;for(const auto c:id)if(c<'0'||c>'9')return false;return true;}
bool GuiState::ensureLoaded(){return loaded_||load();}
bool GuiState::load(){QByteArray bytes;bool exists;if(!read(path_,393216,bytes,exists)){error_="GUI_STATE_UNAVAILABLE";return false;}QString selection,create;QJsonObject grant,geometry;if(exists){QJsonParseError e;const auto d=QJsonDocument::fromJson(bytes,&e);if(e.error!=QJsonParseError::NoError||!d.isObject()){error_="GUI_STATE_INVALID";return false;}const auto o=d.object();for(const auto&key:o.keys())if(key!="version"&&key!="selection"&&key!="pendingCreate"&&key!="pendingGrant"&&key!="geometry"){error_="GUI_STATE_INVALID";return false;}if(o.value("version").toInt()!=1||o.contains("selection")&&!o.value("selection").isString()||o.contains("pendingCreate")&&!o.value("pendingCreate").isString()){error_="GUI_STATE_INVALID";return false;}if(o.contains("geometry")){if(!o.value("geometry").isObject()||!validGeometry(o.value("geometry").toObject())){error_="GUI_STATE_INVALID";return false;}geometry=o.value("geometry").toObject();}selection=o.value("selection").toString();create=o.value("pendingCreate").toString();if(o.contains("pendingGrant")){if(!o.value("pendingGrant").isObject()){error_="GUI_STATE_INVALID";return false;}grant=o.value("pendingGrant").toObject();if(!grant.isEmpty()&&!TildeProtocolV3::validateRequest(QJsonObject{{"v",3},{"id","grant-state"},{"method","budget.extend"},{"params",grant}})){error_="GUI_STATE_INVALID";return false;}}if(!selection.isEmpty()&&!validId(selection)||!literal(create,128)){error_="GUI_STATE_INVALID";return false;}}
 selection_=selection;create_=create;pendingGrant_=grant;geometry_=geometry;original_=bytes;existed_=exists;loaded_=true;error_.clear();return true;}
bool GuiState::save(){if(!ensureLoaded())return false;QByteArray current;bool exists;if(!read(path_,393216,current,exists)||exists!=existed_||current!=original_){error_="GUI_STATE_CHANGED";return false;}const auto bytes=QJsonDocument(QJsonObject{{"version",1},{"selection",selection_},{"pendingCreate",create_},{"pendingGrant",pendingGrant_},{"geometry",geometry_}}).toJson(QJsonDocument::Compact);if(!write(path_,bytes,393216)){error_="GUI_STATE_UNAVAILABLE";return false;}original_=bytes;existed_=true;error_.clear();return true;}
bool GuiState::setSelection(const QString&id){if(!validId(id)||!ensureLoaded()){if(error_.isEmpty())error_="INVALID_CONVERSATION";return false;}const auto before=selection_;selection_=id;if(save())return true;selection_=before;return false;}
bool GuiState::setPendingCreate(const QString&id){if(!literal(id,128)||!ensureLoaded()){if(error_.isEmpty())error_="GUI_STATE_INVALID";return false;}const auto before=create_;create_=id;if(save())return true;create_=before;return false;}
bool GuiState::readDraft(const QString&id,QString&text,QString&revision){if(!validId(id)){error_="INVALID_CONVERSATION";return false;}return readBody(draftPath(path_,id),text,revision);}
bool GuiState::readBody(const QString&path,QString&text,QString&revision){QByteArray bytes;bool exists;if(!read(path,1048576,bytes,exists)){error_="DRAFT_UNAVAILABLE";return false;}if(!exists){text.clear();revision="0";error_.clear();return true;}QJsonParseError e;const auto d=QJsonDocument::fromJson(bytes,&e);const auto o=d.object();bool number=false;const auto rev=o.value("revision").toString();rev.toULongLong(&number);if(e.error!=QJsonParseError::NoError||!d.isObject()||o.keys()!=QStringList({"revision","text","version"})||o.value("version").toInt()!=1||!o.value("text").isString()||!literal(o.value("text").toString(),131072)||!number||rev.isEmpty()||QString::number(rev.toULongLong())!=rev){error_="DRAFT_INVALID";return false;}text=o.value("text").toString();revision=rev;error_.clear();return true;}
void GuiState::remember(const QString&id,const QString&text,const QString&revision){if(drafts_.contains(id))bytes_-=drafts_.value(id).bytes;lru_.removeAll(id);const auto bytes=qint64(text.size()+revision.size()+id.size())*2+256;drafts_.insert(id,{text,revision,bytes});lru_.append(id);bytes_+=bytes;while(lru_.size()>16||bytes_>2*1024*1024){const auto oldest=lru_.takeFirst();bytes_-=drafts_.take(oldest).bytes;}}
QString GuiState::draft(const QString&id){if(drafts_.contains(id)){const auto text=drafts_.value(id).text;lru_.removeAll(id);lru_.append(id);error_.clear();return text;}QString text,revision;if(!readDraft(id,text,revision))return {};remember(id,text,revision);return text;}
QString GuiState::draftRevision(const QString&id){draft(id);return error_.isEmpty()?drafts_.value(id).revision:QString();}
bool GuiState::setDraft(const QString&id,const QString&text){if(!literal(text,131072)){error_="DRAFT_TOO_LARGE";return false;}QString before,revision;if(!readDraft(id,before,revision))return false;bool ok=false;const auto n=revision.toULongLong(&ok);if(!ok||n==std::numeric_limits<quint64>::max()){error_="DRAFT_INVALID";return false;}revision=QString::number(n+1);const auto bytes=QJsonDocument(QJsonObject{{"version",1},{"revision",revision},{"text",text}}).toJson(QJsonDocument::Compact);if(!write(draftPath(path_,id),bytes,1048576)){error_="DRAFT_UNAVAILABLE";return false;}remember(id,text,revision);error_.clear();return true;}

bool GuiState::setPendingGrant(const QJsonObject&grant){if(!ensureLoaded())return false;if(!grant.isEmpty()&&!TildeProtocolV3::validateRequest(QJsonObject{{"v",3},{"id","grant-state"},{"method","budget.extend"},{"params",grant}})){error_="GUI_STATE_INVALID";return false;}const auto before=pendingGrant_;pendingGrant_=grant;if(save())return true;pendingGrant_=before;return false;}

QString GuiState::startupDraft(){QString text,revision;if(!readBody(QFileInfo(path_).absolutePath()+"/pending-draft.json",text,revision))return {};return text;}
bool GuiState::setStartupDraft(const QString&text){if(!literal(text,131072)){error_="DRAFT_TOO_LARGE";return false;}const auto path=QFileInfo(path_).absolutePath()+"/pending-draft.json";QString old,rev;if(!readBody(path,old,rev))return false;bool ok=false;const auto n=rev.toULongLong(&ok);if(!ok||n==std::numeric_limits<quint64>::max()){error_="DRAFT_INVALID";return false;}const auto data=QJsonDocument(QJsonObject{{"version",1},{"revision",QString::number(n+1)},{"text",text}}).toJson(QJsonDocument::Compact);if(!write(path,data,1048576)){error_="DRAFT_UNAVAILABLE";return false;}error_.clear();return true;}

bool GuiState::setGeometry(const QJsonObject&geometry){if(!ensureLoaded()||!validGeometry(geometry)){error_="GUI_STATE_INVALID";return false;}const auto before=geometry_;geometry_=geometry;if(save())return true;geometry_=before;return false;}
